using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;
public static class Harness{
static int checks;
static void Check(bool b,string m){checks++;if(!b)throw new Exception(m+" errors: "+string.Join(" | ",Debug.errors.ToArray()));}
static void Set(object x,string field,object value){x.GetType().GetField(field,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(x,value);}
static void Call(object x,string method){x.GetType().GetMethod(method,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(x,null);}
static UniversalUI SetupUI(){UniversalUI.Instance=null;var go=new GameObject("UI");var child=new GameObject("HUD",typeof(Canvas));child.transform.SetParent(go.transform,false);var ui=go.AddComponent<UniversalUI>();Call(ui,"Awake");return ui;}
static List<TeamData> Teams(){return Enumerable.Range(1,4).Select(i=>new TeamData{name="pokemon_"+i.ToString("D4"),nomeEquipe="Pokemon "+i,sigla="P"+i}).ToList();}
static LigaCampeonato Store(string season){var c=new GameObject("store").AddComponent<LigaCampeonato>();c.ligaId="pokemon_liga";c.temporadaId=season;return c;}
static List<Confronto> Games(List<TeamData> teams){return new List<Confronto>{new Confronto(teams[0],teams[1]),new Confronto(teams[2],teams[3])};}
static TournamentManager Manager(LigaCampeonato store,List<TeamData> teams){TournamentManager.Instance=null;var m=new GameObject("manager").AddComponent<TournamentManager>();m.modoLiga=true;m.iniciarAutomaticamente=false;m.mostrarAbertura=false;m.mostrarClassificacao=false;m.campeonato=store;m.todosOsTimesDisponiveis=teams;m.arquivoCsvCalendario=new TextAsset{text="Rodada,TimeA,TimeB\n1,pokemon_0001,pokemon_0002\n1,pokemon_0003,pokemon_0004\n2,pokemon_0001,pokemon_0003\n2,pokemon_0002,pokemon_0004\n"};var engine=new GameObject("engine").AddComponent<FutebolDeDiscos.PartidaDiscos>();FutebolDeDiscos.PartidaDiscos.Instance=engine;m.simuladorDiscos=engine;Call(m,"Awake");return m;}
static void Finish(TournamentManager m,Confronto c,int a,int b){m.JogarConfronto(c,45);for(int i=0;i<5;i++)Scheduler.Tick();UniversalUI.Instance.PararCronometro();m.FinalizarPartidaEAvancar(a>b,a,b);}
static void ClockCases(){
Scheduler.Reset();TournamentManager.Instance=null;GoalBannerUI.Instance=null;var ui=SetupUI();var engine=new GameObject("clock-engine").AddComponent<FutebolDeDiscos.PartidaDiscos>();FutebolDeDiscos.PartidaDiscos.Instance=engine;var t=Teams();
ui.ConfigurarPartida(t[0],t[1],null,t[0].elenco,t[1].elenco);Check(LayoutJogadorUnicoUI.LastCanvas!=null&&LayoutJogadorUnicoUI.LastCanvas.transform.parent==ui.transform,"player layout resolves child HUD Canvas");Call(ui,"Update");Check(ui.TempoAtual==0&&!ui.partidaEmAndamento,"prepared UI remains frozen before actual start");
ui.IniciarCronometro();Time.captureDeltaTime=.25f;Time.unscaledDeltaTime=.003f;Call(ui,"Update");Check(Math.Abs(ui.TempoAtual-.25f)<.0001f,"capture clock advances by video frames");engine.EmReposicao=true;Call(ui,"Update");Check(Math.Abs(ui.TempoAtual-.25f)<.0001f,"goal reset pauses regulation clock");engine.EmReposicao=false;Time.captureDeltaTime=0;Time.unscaledDeltaTime=.15f;Call(ui,"Update");Check(Math.Abs(ui.TempoAtual-.40f)<.0001f,"live clock uses unscaled delta");
ui.PararCronometro();Check(!ui.partidaEmAndamento&&engine.stops>0,"stopped clock freezes physical match");float stopped=ui.TempoAtual;Call(ui,"Update");Check(ui.TempoAtual==stopped,"stopped clock does not advance");
ui.ConfigurarPartida(t[0],t[1],null,t[0].elenco,t[1].elenco);ui.ativarGoldenGoal=false;ui.duracaoRealEmSegundos=.1f;ui.tempoCongeladoPosJogo=0;ui.IniciarCronometro();engine.EmAndamento=true;GoalBannerUI.Instance=new GameObject("banner").AddComponent<GoalBannerUI>();GoalBannerUI.Instance.TemBannersPendentes=true;Call(ui,"Update");Check(!ui.partidaEmAndamento&&!engine.EmAndamento&&!ui.EmProrrogacao&&ui.GolsA==0&&ui.GolsB==0,"league regulation can finish in a real draw and freezes engine");Scheduler.Tick();Check(Time.timeScale==0,"postmatch waits for actual queued celebration");GoalBannerUI.Instance.TemBannersPendentes=false;Scheduler.Tick();Check(Time.timeScale==1,"postmatch releases only after celebration queue ends");
Scheduler.Reset();GoalBannerUI.Instance=null;ui=SetupUI();ui.ativarGoldenGoal=true;ui.duracaoRealEmSegundos=.1f;ui.tempoCongeladoPosJogo=0;ui.IniciarCronometro();engine.EmAndamento=true;int stopCount=engine.stops;Call(ui,"Update");Check(ui.EmProrrogacao&&ui.partidaEmAndamento&&engine.EmAndamento&&engine.stops==stopCount,"knockout draw enters golden goal with physical play continuing");ui.RegistrarGol(false,ui.TempoAtual);Check(ui.GolsA==0&&ui.GolsB==1&&!ui.partidaEmAndamento&&!engine.EmAndamento,"real golden goal updates score then freezes match");ui.RegistrarGol(true,ui.TempoAtual);Check(ui.GolsA==0&&ui.GolsB==1,"duplicate goal after final is ignored");Scheduler.Tick();Check(!ui.EmProrrogacao,"golden goal ending completes after one frame");ui.ConfigurarPartida(t[0],t[1],null,t[0].elenco,t[1].elenco);ui.IniciarCronometro();engine.EmAndamento=true;ui.CancelarPartida();Check(!ui.partidaEmAndamento&&!ui.EmProrrogacao&&!engine.EmAndamento&&Time.timeScale==1,"cancel clears overtime and freezes simulation");
Scheduler.Reset();GoalBannerUI.Instance=null;SetupUI();
}
static void KnockoutCases(List<TeamData> t){
Scheduler.Reset();var manager=Manager(Store("unused-knockout"),t);manager.modoLiga=false;manager.modoMataMata=true;var mata=manager.gameObject.AddComponent<MataMataCampeonato>();manager.mataMata=mata;mata.tema=new TemaCompeticao{competicaoId="knockout"};mata.edicaoId="knockout-season";mata.tamanhoChave=TamanhoMataMata.Final;mata.participantes=t.Take(2).ToList();mata.gravarSomenteUmaFase=false;mata.Iniciar(manager);for(int i=0;i<15;i++)Scheduler.Tick();Check(mata.Ocupado&&!mata.Concluido&&UniversalUI.Instance.partidaEmAndamento,"knockout opens bracket then starts physical game after cards");Check(manager.simuladorDiscos.prepares==1&&manager.simuladorDiscos.starts==1&&manager.simuladorDiscos.startHadClock&&manager.simuladorDiscos.prepareHadStoppedClock,"physical match preparation and clock/engine start order preserved");Check(object.ReferenceEquals(manager.simuladorDiscos.preparedA,manager.simuladorDiscos.startedA),"photo representative list reused by physical match");var copy=mata.EstadoAtual;string original=mata.EstadoAtual.fases[0].partidas[0].a;copy.fases[0].partidas[0].a="tampered";Check(mata.EstadoAtual.fases[0].partidas[0].a==original,"public bracket state is an independent copy");
var current=(Confronto)typeof(TournamentManager).GetField("confrontoEmAndamento",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(manager);Check(!mata.RegistrarResultado(current,1,1)&&!mata.Concluido,"knockout rejects tied result instead of inventing winner");UniversalUI.Instance.PararCronometro();string saveDir=mata.PastaTorneio,saveHold=saveDir+"_hold";Directory.Move(saveDir,saveHold);File.WriteAllText(saveDir,"obstruction");manager.FinalizarPartidaEAvancar(true,2,1);Check(manager.SalvamentoPendente&&!mata.Concluido&&!current.concluido,"knockout write failure retains pending result without awarding champion");File.Delete(saveDir);Directory.Move(saveHold,saveDir);manager.TentarSalvarUltimoResultado();Check(!manager.SalvamentoPendente,"public pending-result retry also recovers knockout write failure");for(int i=0;i<5;i++)Scheduler.Tick();Check(mata.Concluido&&!string.IsNullOrEmpty(mata.EstadoAtual.campeao)&&current.concluido&&current.pontosRegistrados,"real knockout result persists champion and completion flags");string path=Path.Combine(mata.PastaTorneio,"torneio.json");Check(File.Exists(path),"knockout writes its established tournament save");manager.FinalizarPartidaEAvancar(true,999,0);Check(mata.EstadoAtual.fases[0].partidas[0].golsA==2,"duplicate knockout result callback cannot overwrite final");
Scheduler.Reset();var resumedManager=Manager(Store("unused-knockout-resume"),t);resumedManager.modoLiga=false;resumedManager.modoMataMata=true;var resumed=resumedManager.gameObject.AddComponent<MataMataCampeonato>();resumedManager.mataMata=resumed;resumed.tema=mata.tema;resumed.edicaoId=mata.edicaoId;resumed.tamanhoChave=mata.tamanhoChave;resumed.participantes=t.Take(2).ToList();resumed.Iniciar(resumedManager);for(int i=0;i<6;i++)Scheduler.Tick();Check(resumed.Concluido&&resumedManager.simuladorDiscos.starts==0,"completed knockout reloads champion and never replays final");resumed.ContinuarNoPlay();for(int i=0;i<6;i++)Scheduler.Tick();Check(resumed.Concluido&&resumedManager.simuladorDiscos.starts==0,"public continue leaves completed knockout intact");
Scheduler.Reset();SetupUI();
}
public static void Main(){string root=Path.Combine(Path.GetTempPath(),"league-engine-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);Application.persistentDataPath=root;Application.isPlaying=true;Scheduler.Reset();SetupUI();try{
var t=Teams();ClockCases();KnockoutCases(t);int next;
var fresh=Store("fresh");Check(fresh.TentarObterProximaRodada(out next)&&next==1,"new season starts at one");Check(!File.Exists(Path.Combine(fresh.PastaDaTemporada,"temporada.json")),"query does not write season");
var games=Games(t);Check(fresh.PrepararRodada(1,t,games),"round prepared");Check(fresh.TentarObterProximaRodada(out next)&&next==1,"draft resumes current round");Check(!fresh.ConfirmarRodada(),"partial round cannot confirm");Check(fresh.RegistrarResultado(games[0],2,1),"first result saved");Check(File.Exists(Path.Combine(fresh.PastaDaTemporada,"temporada.json")),"season exists after game");
var resumed=Store("fresh");var resumedGames=Games(t);Check(resumed.TentarObterProximaRodada(out next)&&next==1,"new store resumes draft");Check(resumed.PrepararRodada(1,t,resumedGames),"new store prepares same round");Check(resumedGames[0].concluido&&resumedGames[0].pontosRegistrados&&resumedGames[0].golsA==2,"registered game recovered without replay");Check(!resumedGames[1].concluido&&!resumedGames[1].pontosRegistrados,"pending game stays pending");Check(resumed.RegistrarResultado(resumedGames[1],0,0),"draw saved");var before=resumed.ObterClassificacao(true);Check(before.Single(x=>x.id==t[0].name).PTS==3,"winner receives three");Check(before.Single(x=>x.id==t[2].name).PTS==1,"draw receives one");Check(resumed.ConfirmarRodada(),"complete round confirmed");Check(resumed.ConfirmarRodada(),"confirmation idempotent");Check(resumed.ObterClassificacao(true).All(x=>x.P==1),"confirmation does not duplicate games");Check(resumed.TentarObterProximaRodada(out next)&&next==2,"confirmed round advances query");Check(!resumed.PrepararRodada(1,t,Games(t)),"confirmed round cannot replay");
var reloaded=Store("fresh");Check(reloaded.TentarObterProximaRodada(out next)&&next==2,"new store after confirm returns next round");Check(reloaded.ObterClassificacao(true).Sum(x=>x.PTS)==5,"final table loads with no prepared round");
var bad=Store("bad");Directory.CreateDirectory(bad.PastaDaTemporada);File.WriteAllText(Path.Combine(bad.PastaDaTemporada,"temporada.json"),"invalid-data");Check(!bad.TentarObterProximaRodada(out next)&&next==0&&!string.IsNullOrEmpty(bad.ultimoErro),"corrupt save reports failure and zero");
var other=Store("other");Check(other.TentarObterProximaRodada(out next)&&next==1,"another season independent");
var auto=Manager(Store("auto"),t);auto.arquivoCsvCalendario=null;Debug.errors.Clear();Call(auto,"Start");Check(Debug.errors.Count==0,"automatic start disabled skips CSV load");Check(!auto.LigaPreparada,"disabled start does not prepare league");auto.iniciarAutomaticamente=true;Call(auto,"Start");Check(Debug.errors.Any(x=>x.Contains("CSV")),"automatic start retains CSV validation");
var m=Manager(Store("manager"),t);m.CarregarRodadaDoCSVESeguir();Check(m.LigaPreparada,"manual calendar load prepares league");Check(!m.RodadaConcluida&&!m.EncerramentoRodadaConcluido,"fresh loaded round not complete");Finish(m,m.rodadaAtual[0],2,0);Check(!m.RodadaConcluida,"one result does not complete round");Finish(m,m.rodadaAtual[1],1,1);Check(m.RodadaConcluida&&m.EncerramentoRodadaConcluido,"all saved results complete round without table");m.FinalizarPartidaEAvancar(true,99,0);Check(m.campeonato.ObterClassificacao(true).All(x=>x.P==1),"duplicate callback does not add another result");m.mostrarClassificacao=true;Check(!m.EncerramentoRodadaConcluido,"closing animation required when table enabled");Set(m,"encerramentoExibido",true);Check(m.EncerramentoRodadaConcluido,"completed closing animation opens next round gate");m.classificacaoUI=new GameObject("table").AddComponent<ClassificacaoUI>();m.classificacaoUI.EstaExibindo=true;Check(!m.EncerramentoRodadaConcluido,"active table holds transition");m.classificacaoUI.EstaExibindo=false;Set(m,"preparandoPartida",true);Check(!m.RodadaConcluida,"preparation prevents completion");Set(m,"preparandoPartida",false);Set(m,"registroPendente",true);Check(m.SalvamentoPendente&&!m.RodadaConcluida,"pending save prevents completion");Set(m,"registroPendente",false);m.rodadaAtual[0].pontosRegistrados=false;Check(!m.RodadaConcluida,"unsaved completed flag does not complete round");m.rodadaAtual[0].pontosRegistrados=true;Check(m.RodadaConcluida,"saved flags restore completion gate");
var fail=Manager(Store("retry"),t);fail.CarregarRodadaDoCSVESeguir();var current=fail.rodadaAtual[0];fail.JogarConfronto(current,45);for(int i=0;i<5;i++)Scheduler.Tick();UniversalUI.Instance.PararCronometro();string dir=fail.campeonato.PastaDaTemporada,backup=dir+"_hold";Directory.Move(dir,backup);File.WriteAllText(dir,"obstruction");fail.FinalizarPartidaEAvancar(true,3,1);Check(fail.SalvamentoPendente&&!current.concluido&&!fail.RodadaConcluida,"write failure holds result and progression");File.Delete(dir);Directory.Move(backup,dir);fail.TentarSalvarUltimoResultado();Check(!fail.SalvamentoPendente&&current.concluido&&current.pontosRegistrados,"retry records retained result once");var again=Store("retry");var againGames=Games(t);Check(again.PrepararRodada(1,t,againGames)&&againGames[0].golsA==3&&!againGames[1].concluido,"retry result persists across new store");
Console.WriteLine("PASS storage resumes pending rounds and confirmed next-round selection");Console.WriteLine("PASS game persistence, standings, draws, idempotence and corrupt-save guards");Console.WriteLine("PASS manager manual start, completion gates and pending save recovery");Console.WriteLine("PASS recording clock, reposicao, league draw, real golden goal, and child Canvas");Console.WriteLine("PASS knockout preparation order, representative reuse, state copy, champion persistence and resume");Console.WriteLine("PASS "+checks+" assertions on real TM/Liga/UniversalUI/Mata/Modelo/CSV sources with Unity stubs");
}finally{Directory.Delete(root,true);}}
}
